<script setup>
import { computed, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Plus, Search, Grid, List, Download, ArrowRight } from '@element-plus/icons-vue'
import { api, exportCsv } from '../api'
import { state, refresh, isAdmin, branch, rule, money, labels, dateText } from '../store'
import VehicleThumbnail from '../components/VehicleThumbnail.vue'
import StatusTag from '../components/StatusTag.vue'
import FormDialog from '../components/FormDialog.vue'
const route = useRoute(), router = useRouter(), query = reactive({ search: '', status: route.query.status || '', branch: Number(route.query.branch) || '' }), view = ref('grid'), page = ref(1), open = ref(false), detail = ref(null), edit = ref(null), initial = ref({}), busy = ref(false)
const filtered = computed(() => state.vehicles.filter(item => (!query.search || `${item.plate}${item.brand}${item.model}`.toLowerCase().includes(query.search.toLowerCase())) && (!query.status || item.status === query.status) && (!query.branch || item.branch_id === query.branch)))
const rows = computed(() => filtered.value.slice((page.value - 1) * 9, page.value * 9))
watch(query, () => page.value = 1)
watch(() => route.query.status, value => query.status = value || '')
watch(() => route.query.branch, value => query.branch = Number(value) || '')
const fields = computed(() => [
  { key: 'plate', label: '车牌号', maxlength: 12 }, { key: 'brand', label: '品牌', maxlength: 50 }, { key: 'model', label: '车型名称', maxlength: 80 },
  { key: 'category', label: '车辆类别', type: 'select', options: ['经济轿车', 'SUV', '新能源', '商务 MPV'].map(value => ({ label: value, value })) },
  { key: 'color', label: '颜色' }, { key: 'seats', label: '座位数', type: 'number', min: 1, max: 50 },
  { key: 'purchase_date', label: '购置日期', type: 'date' }, { key: 'license_no', label: '行驶证编号' },
  { key: 'mileage', label: '当前里程（km）', type: 'number', max: 2000000 },
  { key: 'branch_id', label: '所属门店', type: 'select', disabled: !!edit.value, options: state.branches.map(item => ({ label: item.name, value: item.id })), tip: edit.value ? '变更门店请使用调度模块' : '' },
  { key: 'pricing_id', label: '计费规则', type: 'select', options: state.pricing.map(item => ({ label: item.name, value: item.id })) },
  { key: 'next_service_date', label: '下次保养日期', type: 'date', required: false }, { key: 'next_service_mileage', label: '下次保养里程（km）', type: 'number' },
  { key: 'image', label: '车辆照片', type: 'upload', required: false, wide: true },
])
function create(car) { edit.value = car?.id || null; initial.value = car ? { ...car } : { seats: 5, mileage: 0, branch_id: state.branches[0]?.id, pricing_id: state.pricing[0]?.id, category: '经济轿车', next_service_mileage: 5000, image: '' }; open.value = true }
async function save(data) { busy.value = true; try { const result = await api[edit.value ? 'put' : 'post']('/vehicles' + (edit.value ? '/' + edit.value : ''), data); open.value = false; await refresh(); if (detail.value?.id === result.id) detail.value = result; ElMessage.success('车辆档案已保存') } catch {} finally { busy.value = false } }
async function toggle(car) { try { await ElMessageBox.confirm(`确认${car.status === 'DISABLED' ? '启用' : '停用'} ${car.plate}？`, '车辆状态'); await api.post(`/vehicles/${car.id}/toggle`); await refresh(); detail.value = null; ElMessage.success('车辆状态已更新') } catch {} }
function exportData() { exportCsv(filtered.value, [{ label: '车牌', value: 'plate' }, { label: '品牌', value: 'brand' }, { label: '车型', value: 'model' }, { label: '门店', value: row => branch(row.branch_id).name }, { label: '状态', value: row => labels[row.status] }, { label: '里程', value: 'mileage' }], '车辆档案.csv') }
function clearBranchScope() {
  const nextQuery = { ...route.query }
  delete nextQuery.branch
  router.replace({ path: route.path, query: nextQuery })
}
</script>

<template>
  <div class="module-overview"><div><strong>{{ state.vehicles.length }}</strong><span>全部车辆</span></div><div><strong class="text-accent">{{ state.vehicles.filter(car => car.status === 'AVAILABLE').length }}</strong><span>当前可用</span></div><div><strong>{{ state.vehicles.filter(car => car.status === 'RENTED').length }}</strong><span>出租中</span></div><div><strong>{{ state.vehicles.filter(car => ['MAINTENANCE', 'DISPATCHING'].includes(car.status)).length }}</strong><span>维修 / 调度</span></div><el-button type="primary" :icon="Plus" @click="create()">新增车辆</el-button></div>
  <section class="panel listing-panel"><div class="filter-bar"><el-input v-model="query.search" placeholder="搜索车牌、品牌、车型" :prefix-icon="Search" clearable class="search-input"/><el-select v-model="query.status" placeholder="全部状态" clearable><el-option v-for="status in ['AVAILABLE', 'RENTED', 'MAINTENANCE', 'DISPATCHING', 'DISABLED']" :key="status" :label="labels[status]" :value="status"/></el-select><el-tag v-if="query.branch" class="vehicle-branch-scope" closable type="info" @close="clearBranchScope">调度筛选：{{ branch(query.branch).name }}</el-tag><div class="filter-spacer"></div><el-button :icon="Download" @click="exportData">导出</el-button><div class="view-switch"><button :class="{ active: view === 'grid' }" title="卡片视图" @click="view = 'grid'"><el-icon><Grid /></el-icon></button><button :class="{ active: view === 'list' }" title="列表视图" @click="view = 'list'"><el-icon><List /></el-icon></button></div></div><div class="listing-caption"><span>车队档案 <small>{{ filtered.length }} 辆</small></span><span>车辆状态由交车、还车、调度及维修业务同步</span></div>
    <div v-if="view === 'grid' && rows.length" class="vehicle-grid"><article v-for="car in rows" :key="car.id" class="vehicle-card"><div class="vehicle-card-art" role="button" tabindex="0" :aria-label="`查看 ${car.brand} ${car.model} ${car.plate} 的车辆档案`" @click="detail = car" @keydown.enter="detail = car" @keydown.space.prevent="detail = car"><span class="car-category">{{ car.category }}</span><StatusTag :value="car.status"/><VehicleThumbnail :vehicle="car" size="card"/></div><div class="vehicle-card-body"><div class="vehicle-title"><div><h3>{{ car.brand }} {{ car.model }}</h3><span>{{ car.plate }}</span></div><span class="daily-price">¥{{ Number(rule(car.pricing_id).daily_rate) }}<small>/ 天</small></span></div><div class="vehicle-specs"><span>{{ car.seats }} 座</span><i></i><span>{{ car.color }}</span><i></i><span>{{ Number(car.mileage).toLocaleString() }} km</span></div><div class="vehicle-card-footer"><span><i class="location-dot"></i>{{ branch(car.branch_id).name }}</span><button @click="detail = car">查看档案<el-icon><ArrowRight /></el-icon></button></div></div></article></div>
    <el-table v-else-if="view === 'list'" :data="rows"><el-table-column label="车辆" min-width="250"><template #default="{ row }"><div class="vehicle-table-identity"><VehicleThumbnail :vehicle="row"/><div><strong class="cell-title">{{ row.brand }} {{ row.model }}</strong><small class="cell-sub">{{ row.plate }}</small></div></div></template></el-table-column><el-table-column prop="category" label="类别"/><el-table-column label="门店"><template #default="{ row }">{{ branch(row.branch_id).name }}</template></el-table-column><el-table-column prop="mileage" label="里程（km）"/><el-table-column label="状态"><template #default="{ row }"><StatusTag :value="row.status"/></template></el-table-column><el-table-column label="操作" width="140"><template #default="{ row }"><el-button link type="primary" @click="detail = row">详情</el-button><el-button link type="primary" @click="create(row)">编辑</el-button></template></el-table-column></el-table>
    <el-empty v-else description="没有符合条件的车辆，试试调整筛选条件"/>
    <div class="pagination"><span>共 {{ filtered.length }} 辆车辆</span><el-pagination v-model:current-page="page" :page-size="9" :total="filtered.length" layout="prev, pager, next"/></div>
  </section>
  <FormDialog v-model="open" :title="edit ? '编辑车辆档案' : '新增车辆'" :fields="fields" :initial="initial" :busy="busy" @submit="save"/>
  <el-drawer :model-value="!!detail" @close="detail = null" title="车辆档案" size="580px"><template v-if="detail"><div class="detail-car"><VehicleThumbnail :vehicle="detail" size="detail"/><h2>{{ detail.brand }} {{ detail.model }}</h2><p>{{ detail.plate }} <StatusTag :value="detail.status"/></p></div><el-descriptions :column="2" border><el-descriptions-item label="所属门店">{{ branch(detail.branch_id).name }}</el-descriptions-item><el-descriptions-item label="当前里程">{{ detail.mileage }} km</el-descriptions-item><el-descriptions-item label="颜色 / 座位">{{ detail.color }} / {{ detail.seats }} 座</el-descriptions-item><el-descriptions-item label="购置日期">{{ detail.purchase_date }}</el-descriptions-item><el-descriptions-item label="行驶证">{{ detail.license_no }}</el-descriptions-item><el-descriptions-item label="计费规则">{{ rule(detail.pricing_id).name }}</el-descriptions-item><el-descriptions-item label="下次保养">{{ detail.next_service_date || '未设置' }}</el-descriptions-item><el-descriptions-item label="保养里程">{{ detail.next_service_mileage }} km</el-descriptions-item></el-descriptions><div class="drawer-actions"><el-button type="primary" @click="create(detail)">编辑档案</el-button><el-button v-if="detail.status === 'AVAILABLE'" @click="router.push('/orders?create=1&vehicle=' + detail.id)">创建订单</el-button><el-button v-if="isAdmin && ['AVAILABLE', 'DISABLED'].includes(detail.status)" @click="toggle(detail)">{{ detail.status === 'DISABLED' ? '启用' : '停用' }}</el-button></div><h3 class="section-title">历史租赁订单</h3><el-table :data="state.orders.filter(order => order.vehicle_id === detail.id)"><el-table-column prop="order_no" label="订单" min-width="160"/><el-table-column label="时间"><template #default="{ row }">{{ dateText(row.planned_start) }}</template></el-table-column><el-table-column label="状态"><template #default="{ row }"><StatusTag :value="row.status"/></template></el-table-column></el-table><h3 class="section-title">维修保养记录</h3><el-table :data="state.maintenance.filter(task => task.vehicle_id === detail.id)"><el-table-column prop="project" label="项目"/><el-table-column label="状态"><template #default="{ row }"><StatusTag :value="row.status"/></template></el-table-column><el-table-column label="费用"><template #default="{ row }">¥{{ money(row.cost) }}</template></el-table-column></el-table></template></el-drawer>
</template>
